package net.civeira.phylax.features.access.userinvitation.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.userinvitation.domain.UserInvitation;
import net.civeira.phylax.features.access.userinvitation.domain.gateway.UserInvitationCursor;
import net.civeira.phylax.features.access.userinvitation.domain.gateway.UserInvitationFilter;

class UserInvitationSlider extends Slider<UserInvitation> {

  /**
   * @autogenerated SlideGenerator
   */
  private final UserInvitationCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final UserInvitationFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<UserInvitationFilter, UserInvitationCursor, Iterator<UserInvitation>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  UserInvitationSlider(final Iterator<UserInvitation> multi, final int limit,
      final BiFunction<UserInvitationFilter, UserInvitationCursor, Iterator<UserInvitation>> gateway,
      final UserInvitationFilter filter, final UserInvitationCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param userInvitations
   * @param limit
   * @return
   */
  @Override
  public Iterator<UserInvitation> next(List<UserInvitation> userInvitations, int limit) {
    UserInvitation last = userInvitations.get(userInvitations.size() - 1);
    UserInvitationCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
